INSERT INTO products (id, name, brand, category, image_url, description, budget_level, suitable_for_sensitive) VALUES
(1, '2% Salicylic Acid Face Serum', 'Minimalist', 'Serum', 'https://i.ibb.co/tTbyTsvy/Whats-App-Image-1948-08-28-at-20-20-43.jpg', 'For blemish-prone skin; introduce gradually. Avoid combining several strong exfoliants at once.', NULL, FALSE),
(2, '2% Salicylic Acid Serum', 'The Derma Co', 'Serum', 'https://i.ibb.co/93CQP0D8/Whats-App-Image-1948-08-28-at-20-20-41.jpg', 'A leave-on exfoliating serum marketed for acne-prone skin. Check the current formula and directions.', NULL, FALSE),
(3, 'Oil-Free Acne Wash', 'Neutrogena', 'Cleanser', 'https://i.ibb.co/BVnzZHqs/Neutrogena-Oil-Free-Acne-Wash.jpg', 'A cleanser option for oily or blemish-prone skin. Check the local formulation and suitability.', NULL, FALSE),
(4, 'Alpha Arbutin 2% Serum', 'Minimalist', 'Serum', 'https://i.ibb.co/5hrDJ2yJ/Minimalist-Alpha-Arbutus-2-Serum.jpg', 'A targeted serum marketed for the appearance of pigmentation and uneven tone.', NULL, FALSE),
(5, '2% Kojic Acid Face Serum', 'The Derma Co', 'Serum', 'https://i.ibb.co/ccP3rfS6/The-Derma-Co-2-Kojic-Acid-face-Serum.jpg', 'A brightening serum marketed for the appearance of dark spots. Check ingredient list and directions.', NULL, FALSE),
(6, 'Alpha Arbutin 2% + HA', 'The Ordinary', 'Serum', 'https://i.ibb.co/HDn9PH26/The-Ordinary-Alpha-Arbutin-2-HA.jpg', 'A serum option for uneven-looking tone; verify authorised seller and local availability.', NULL, FALSE),
(7, 'Retinol 0.3% Serum', 'Minimalist', 'Serum', 'https://i.ibb.co/nMSXwXHW/Minimalist-Retinol-0-3-Serum.jpg', 'A retinol product marketed for fine-line care. Not a beginner product for everyone; follow directions and sun-protection guidance.', NULL, FALSE),
(8, 'Regenerist Micro-Sculpting Cream', 'Olay', 'Moisturizer', 'https://i.ibb.co/zT3PSmYx/Olay-Regenerist-Micro-Sculpting-Cream.jpg', 'A moisturizer marketed for mature-skin care. Check exact variant and ingredient list.', NULL, FALSE),
(9, 'Revitalift Hyaluronic Acid Serum', 'L''Oréal Paris', 'Serum', 'https://i.ibb.co/MDqQfwNj/L-Or-al-Pari-Revitalift-Hyaluronic-Acid-Serum.jpg', 'Hydrating serum; supports skin hydration and the appearance of plumper skin.', NULL, FALSE),
(10, 'Vitamin C Booster Serum', 'Garnier', 'Serum', 'https://i.ibb.co/sJsrQ4yk/Garnier-Vitamin-C-Booster-Serum.jpg', 'A brightening serum marketed for dull-looking skin. Formula differs by market/version.', NULL, FALSE),
(11, 'Vitamin C 10% Serum', 'Minimalist', 'Serum', 'https://i.ibb.co/XfTG8XpZ/Minimilist-Vitamin-C-10-Serum.jpg', 'A vitamin C serum marketed for glow and uneven-looking tone.', NULL, FALSE),
(12, '15% Vitamin C Face Serum', 'Plum', 'Serum', 'https://i.ibb.co/zhWphyL5/Plum-15-Vitamin-C-Face-Serum.jpg', 'A vitamin C serum option for a brighter-looking complexion. Check current formula and directions.', NULL, FALSE),
(13, 'Moisturising Cream', 'Cetaphil', 'Cream', 'https://i.ibb.co/v4HrdHsB/Cetaphil-Moisturising-Cream.jpg', 'A richer moisturizer designed for dry and sensitive-feeling skin.', NULL, TRUE),
(14, 'Moisturising Cream', 'CeraVe', 'Cream', 'https://i.ibb.co/spsy1KSP/Cera-Ve-Moisturising-Cream.jpg', 'A rich moisturizer designed to support the skin barrier; check local availability.', NULL, TRUE),
(15, 'Soft Light Moisturiser', 'Nivea', 'Cream', 'https://i.ibb.co/21h5WS1M/Nivea-Soft-Light-Moisturiser.jpg', 'A lighter everyday moisturizer; suitability depends on individual preference and formula.', NULL, FALSE),
(16, 'Sensibio Defensive', 'Bioderma', 'Moisturizer', 'https://i.ibb.co/bjq2vwM2/Bioderma-Sensibio-Defensive.jpg', 'A moisturizer range designed for sensitive skin; verify the exact variant.', NULL, TRUE),
(17, 'Moisturising Lotion', 'Cetaphil', 'Lotion', 'https://i.ibb.co/pBjRGTNY/Cetaphil-Moisturising-Lotion.jpg', 'A simple moisturizing option for dry or sensitive-feeling skin.', NULL, TRUE),
(18, 'Toleriane Dermallergo Cream', 'La Roche-Posay', 'Cream', 'https://i.ibb.co/7dLK5Mj9/La-Roache-Posay-Toleriane-Dermallergo-Cream.jpg', 'A sensitive-skin moisturizer; confirm local availability and exact formulation.', NULL, TRUE);
